// Mỗi dòng được biên soạn từ mô tả riêng của hồ sơ nguồn, không dùng nhận xét sao/rating tự sinh.
const entries=[
 ['Long Trieu','Món Quảng Đông trong không gian nhà hàng tại The Reverie Saigon.','Thực đơn có món gọi riêng và thực đơn theo bộ; tôm xốt XO cùng súp hoành thánh chua cay là hai gợi ý trong hồ sơ nguồn.','Tôm xốt XO|Hoành thánh chua cay|Món Quảng Đông','Hỏi vị trí tầng 4 và khẩu phần nếu dùng bữa theo nhóm.'],
 ['Square One','Hai lựa chọn món Việt và món Pháp trong cùng một nhà hàng.','Bếp mở giúp quan sát quá trình nấu. Nhiều món có khẩu phần để chia sẻ, hợp một bữa ăn cùng gia đình hoặc bạn bè.','Món Việt|Món Pháp|Bếp mở','Nếu đi một mình, hỏi thực đơn hoặc khẩu phần phù hợp trước khi gọi.'],
 ['Coco Dining','Thực đơn nếm thử theo mùa, lấy cảm hứng từ món Việt.','Các món được sắp xếp theo chủ đề của bếp. Khu CoCo Grill bên cạnh có lựa chọn gọi món riêng và không khí thoải mái hơn.','Thực đơn theo chủ đề|Món Việt đương đại|Lựa chọn CoCo Grill','Xác nhận bạn đặt khu Dining hay Grill vì hình thức phục vụ khác nhau.'],
 ['Chay Garden (Xuan Hoa)','Bữa chay trong ngôi nhà có khoảng sân nhiều cây.','Món Việt được chế biến từ thực vật; nguồn giới thiệu món cà tím om cùng chuối và đậu. Các phòng ăn nhỏ tạo không gian riêng hơn khu sân.','Ẩm thực chay|Sân cây xanh|Phòng ăn nhỏ','Hỏi thành phần nước sốt và yêu cầu thuần chay khi đặt món.'],
 ['Chị Mơ','Phở và các món nướng kết hợp nguyên liệu Việt với cách nấu hiện đại.','Không gian có sân vườn và các loại gia vị lên men tự làm. Hồ sơ nguồn giới thiệu ba lựa chọn nước phở cùng món cá lăng nướng ăn với bánh đa.','Phở|Cá lăng nướng|Gia vị lên men','Hỏi các lựa chọn nước dùng và khẩu phần trước khi chọn một bữa nhiều món.'],
 ['Bếp Mẹ ỉn (Le Thanh Ton Street)','Bánh xèo và món cơm Việt trong con hẻm gần chợ Bến Thành.','Quán có tường vàng, cửa chớp và bàn ghế gỗ gợi không khí nhà quê. Bánh xèo tôm thịt và cơm chiên tôm trứng trong trái dừa là các món được nguồn nhắc tới.','Bánh xèo tôm thịt|Cơm chiên trái dừa|Gần chợ Bến Thành','Kiểm tra đúng chi nhánh Lê Thánh Tôn trước khi đặt xe.'],
 ['Mammom','Món cơm nhà từ ba miền, phục vụ theo cách chia sẻ.','Thực đơn lấy cảm hứng từ bữa ăn gia đình Việt. Canh nghêu với cà chua và dứa là một lựa chọn được nguồn giới thiệu.','Cơm nhà ba miền|Canh nghêu|Bữa ăn nhóm','Chọn món mặn, rau và canh để ghép thành bữa cơm vừa số người.'],
 ['La Lola','Ẩm thực Địa Trung Hải với tôm tỏi và thịt heo Ibérico.','Không gian có mặt tiền cam, nền gạch và ghế nhung. Nhiều phần ăn phù hợp chia sẻ, với lựa chọn đồ uống dùng cùng bữa.','Tôm tỏi ớt|Heo Ibérico|Phần ăn chia sẻ','Hỏi độ cay của món tôm và cách chia khẩu phần khi đi nhóm.'],
 ['Rang','Món Ấn với cà ri, bánh naan và cơm biryani.','Hai đầu bếp gốc Ấn kết hợp kinh nghiệm nấu ăn quốc tế trong thực đơn. Chicken tikka, dal tadka và các loại bánh là những gợi ý để bắt đầu.','Chicken tikka|Dal tadka|Biryani','Chọn độ cay và gọi cơm hoặc bánh ăn cùng cà ri.'],
 ['Zao','Món Việt được biến tấu trong không gian có ghế quầy nhìn bếp.','Thực đơn kết hợp nguyên liệu địa phương với cách nấu quốc tế. Nguồn giới thiệu món cà chua kiểu bingsu, pâté ốc móng tay và cá hồi ăn với rau mầm.','Ghế quầy nhìn bếp|Cà chua bingsu|Thực đơn đương đại','Khi đặt bàn, chọn góc yên tĩnh hoặc ghế quầy theo cách bạn muốn dùng bữa.'],
 ['Fashionista Café','Phở vịt và món Âu trong không gian gắn với cửa hàng thời trang.','Bạn có thể chọn khu nhiều ánh sáng hoặc bàn ở tầng lửng. Nước phở có nấm truffle đi cùng vịt nướng là món biến tấu được hồ sơ nguồn giới thiệu.','Phở vịt biến tấu|Khu nhiều ánh sáng|Bàn tầng lửng','Đây là nơi có phục vụ bữa ăn; xem thực đơn nếu bạn chỉ muốn ghé uống.'],
 ['Stoker (Saigon)','Bít tết và các loại sốt nhà làm trong không gian nhiều tầng.','Tầng trệt có quầy bar và bếp mở; các tầng trên dùng gỗ tối màu và ghế da. Thực đơn tập trung vào bò, trong đó có lựa chọn thịt ủ khô.','Bít tết|Thịt bò ủ khô|Bếp mở','Hỏi phần cắt, trọng lượng và độ chín trước khi gọi bít tết.'],
 ['Kobe Bistro','Bít tết Wagyu cùng các món Pháp trong thực đơn kiểu bistro.','Bếp giới thiệu bò Kobe và các lựa chọn Wagyu, bên cạnh súp cá bouillabaisse và đùi vịt confit. Các loại sốt được phục vụ theo lựa chọn món.','Wagyu|Bouillabaisse|Vịt confit','Xác nhận giống bò, phần cắt và trọng lượng trên thực đơn hiện tại.'],
 ['Bờm','Món Việt được làm thành những phần nhỏ, dễ ghép một bữa nếm thử.','Không gian kết hợp tre với bề mặt xi măng. Thực đơn có bánh tart bò kho, bộ món nhỏ Bờm Set và món ngọt nhân mè đen.','Tart bò kho|Bờm Set|Mè đen','Hỏi số phần trong bộ món để chọn vừa đủ số người.'],
 ['Chapter','Thực đơn nếm thử với bếp than và nguyên liệu gắn với miền Bắc.','Bếp mở nằm sau mặt tiền các thanh thép. Mỗi món trong thực đơn được kể cùng câu chuyện về nguyên liệu và văn hóa ẩm thực Việt.','Bếp than|Thực đơn nếm thử|Nguyên liệu miền Bắc','Dành thời gian cho cả thực đơn và báo trước các món cần tránh.'],
 ['Sóno','Món nướng và các bộ thực đơn theo chủ đề trong không gian ánh sáng dịu.','Bếp mở là tâm điểm của phòng ăn. Bạn có thể chọn món riêng hoặc thực đơn nếm thử, với danh sách rượu gồm cả các lựa chọn rượu tự nhiên.','Bếp mở|Món nướng|Thực đơn theo chủ đề','Nguồn khuyến nghị đặt chỗ; xác nhận hình thức thực đơn trước khi đến.'],
 ['Lüne','Món Pháp được trình bày theo phong cách hiện đại.','Nhà hàng có phòng riêng cho những bữa ăn dịp đặc biệt. Raviolo nhân tôm hùm Canada dùng với xốt kem tôm hùm là món nguồn giới thiệu.','Ẩm thực Pháp|Raviolo tôm hùm|Phòng ăn riêng','Hỏi điều kiện đặt phòng riêng và thực đơn của ngày bạn đến.'],
 ['Okra FoodBar','Bữa ăn quanh quầy bếp, với món nướng và cảm hứng từ đồ ăn đường phố.','Nguyên liệu địa phương được chế biến bằng cả kỹ thuật truyền thống lẫn hiện đại. Không gian có ghế quầy, rượu vang và cocktail để dùng cùng món ăn.','Quầy nhìn bếp|Món nướng than|Cocktail','Hồ sơ ghi quán đã chuyển địa điểm; đối chiếu địa chỉ hiện tại khi đặt xe.'],
 ['Senté (Nguyen Quang Bich Street)','Bữa ăn trong ngõ nhỏ với nhiều món lấy cảm hứng từ cây sen.','Thực đơn dùng hoa, lá, hạt, củ và thân sen trong các món Việt hiện đại. Gỏi tôm, bưởi và củ sen là một lựa chọn được nguồn giới thiệu.','Nguyên liệu từ sen|Gỏi tôm bưởi|Không gian cây xanh','Nguồn khuyến nghị đặt bàn; nhớ chọn đúng chi nhánh Nguyễn Quang Bích.'],
 ['Tanh Tách','Các món cá và hải sản chế biến theo kỹ thuật Âu trong biệt thự cũ.','Phòng ăn trải trên hai tầng. Nguồn nhắc tới bánh gạo với rong biển hoặc kimchi cùng sốt tom yum, bên cạnh nước dùng gà đen.','Hải sản|Biệt thự cũ|Nước dùng gà đen','Hỏi hải sản trong ngày và thành phần sốt nếu bạn cần tránh dị ứng.'],
 ['Vien Dining','Món Việt theo mùa, với lựa chọn gọi món hoặc dùng thực đơn theo bộ.','Bếp mở nằm ở tầng trệt, còn tầng trên có phòng ăn riêng. Nước Junbucha tự làm là một lựa chọn đồ uống được hồ sơ nguồn nhắc tới.','Thực đơn theo mùa|Bếp mở|Junbucha','Thực đơn theo mùa cần đặt trước; xác nhận cùng nhà hàng khi giữ chỗ.'],
 ['Esta','Món Á đương đại quanh quầy bếp, nổi bật với vịt nướng than.','Thực đơn kết hợp kinh nghiệm của bếp với hương vị Việt. Vịt được hong trước khi nướng, dùng cùng nước xốt vịt nhà làm.','Ghế quầy bếp|Vịt nướng than|Hương vị Á','Báo trước các nguyên liệu cần tránh khi chọn thực đơn.'],
 ['La Fontaine','Bistro kiểu Pháp với bánh, món nguội và các món hầm.','Không gian mang nét Paris cổ điển. Thực đơn có bánh mì kẹp, terrine thịt heo, pâté en croûte và cừu hầm kiểu Provence.','Bistro Pháp|Món nguội|Cừu hầm Provence','Xem thực đơn của khung giờ bạn ghé vì bữa sáng và bữa tối khác nhau.'],
 ['NÔM','Thực đơn nếm thử đi qua hương vị Bắc, Trung và Nam.','Những món quen như bún bò Huế và canh cá được làm lại theo cách hiện đại. Từng tầng phòng ăn cũng lấy cảm hứng từ một miền của Việt Nam.','Hương vị ba miền|Thực đơn nếm thử|Món Việt đương đại','Dành thời gian cho toàn bộ thực đơn thay vì ghé như một quán bún thông thường.'],
 ['MÀU','Món Á có điểm nhấn Việt, phục vụ quanh quầy bar và bếp.','Bạn có thể chọn các món riêng hoặc dùng thực đơn của đầu bếp. Không gian có không khí trò chuyện, với nhân viên hỗ trợ lựa chọn đồ uống dùng cùng bữa.','Ghế quầy|Thực đơn đầu bếp|Hương vị Á','Chọn ghế quầy nếu muốn quan sát bếp, hoặc hỏi bàn nhóm khi đặt chỗ.'],
 ['Nephele','Bữa tối theo một thực đơn nếm thử trong tòa nhà được cải tạo.','Trải nghiệm đi qua khu đón ở tầng trệt, phòng ăn phía trên và quầy bar cuối bữa. Có lựa chọn ghép đồ uống có cồn hoặc không cồn.','Bữa tối nếm thử|Ghép đồ uống|Không gian nhiều tầng','Xác nhận thời gian bắt đầu và thời lượng phục vụ với nhà hàng.'],
 ['Truffle','Thực đơn theo mùa của nấm truffle, nhìn ra thành phố từ Landmark 81.','Phòng ăn có cửa kính lớn. Mỗi bộ món dùng các loại truffle theo mùa từ những vùng khác nhau, cùng các lựa chọn bánh do bếp chuẩn bị.','Nấm truffle|Landmark 81|Tầm nhìn thành phố','Xác nhận tầng, lối lên và thực đơn đang phục vụ khi đặt bàn.'],
 ['Tales by Chapter','Thực đơn từ thực vật, dùng nguyên liệu địa phương và kỹ thuật lên men.','Bếp có khu ghế quầy cho khách quan sát. Món bột lọc nhân nấm và các phần nhỏ từ ngô thể hiện cách làm mới món Việt trong thực đơn theo mùa.','Ẩm thực từ thực vật|Lên men|Thực đơn theo mùa','Báo rõ yêu cầu thuần chay và lựa chọn đồ uống không cồn khi đặt chỗ.'],
 ['Apero','Món Ý trong không gian sáng, có bếp mở.','Mì carbonara và tiramisu nhà làm là hai gợi ý trong hồ sơ nguồn. Lựa chọn bữa trưa được giữ gọn hơn so với buổi tối.','Mì carbonara|Tiramisu|Bếp mở','Nếu muốn nghe piano, xác nhận lịch biểu diễn hiện tại cùng quán.'],
 ['Madame Lam','Món miền Trung được biến tấu trong không gian Đông Dương và Art Deco.','Thực đơn có bào ngư nướng mỡ hành. Kem chuối nước cốt dừa với lạc là một lựa chọn để kết thúc bữa ăn.','Bào ngư nướng|Kem chuối|Hương vị miền Trung','Hỏi thực đơn hiện tại và số lượng người phù hợp cho từng món.'],
 ['La Maison 1888','Thực đơn Pháp theo bộ trong khu nghỉ dưỡng InterContinental Đà Nẵng.','Nguồn giới thiệu các bộ năm hoặc tám món, dùng nguyên liệu Việt Nam, Pháp và Nhật Bản; có món gnocchi dùng với nấm truffle.','Thực đơn theo bộ|Ẩm thực Pháp|Khu nghỉ dưỡng Sơn Trà','Nguồn ghi tạm phục vụ tại Club Lounge; xác nhận đúng nơi đón và đặt bàn trước.'],
 ['Hibana by Koki','Trải nghiệm teppanyaki tại quầy trong khách sạn Capella Hà Nội.','Đầu bếp chế biến ngay trước mặt khách. Thực đơn dùng nguyên liệu từ Nhật Bản như bào ngư, tôm hùm gai, nhum và thịt bò.','Teppanyaki|Ghế quầy|Nguyên liệu Nhật','Quầy có số chỗ hạn chế; đặt trước và báo các nguyên liệu bạn cần tránh.'],
 ['Vietnam House','Món Việt được làm mới, trong tòa nhà mang kiến trúc Pháp.','Thực đơn có mì vịt, gà nướng than và món đậu hũ tráng miệng. Nhiều phần ăn phù hợp chia sẻ, còn thực đơn trưa có lựa chọn cho người đi một mình.','Món Việt hiện đại|Gà nướng than|Thực đơn trưa','Hỏi khẩu phần nếu dùng bữa một mình hoặc muốn chọn nhiều món cho nhóm.'],
 ['Backstage','Phở và bún chả theo cách chế biến hiện đại trong không gian chủ đề sân khấu.','Bếp mở là trung tâm phòng ăn, xung quanh là các chi tiết gợi nhà hát và trang phục biểu diễn. Nhà hàng có danh sách cocktail để dùng cùng bữa.','Capella Phở|Bún chả Hà Nội|Không gian sân khấu','Xác nhận bạn đặt Backstage hay nhà hàng khác trong khách sạn Capella.'],
 ['CieL','Thực đơn nếm thử kết hợp kỹ thuật Pháp và nguyên liệu Việt ở Thảo Điền.','Biệt thự có khu ghế quầy nhìn bếp, vườn nhiệt đới và tầng trên mang phong cách Bắc Âu. Nguồn giới thiệu một món kết hợp bong bóng cá với kem trứng.','Thực đơn nếm thử|Ghế quầy|Biệt thự Thảo Điền','Hỏi thực đơn theo mùa và lựa chọn ghép rượu khi đặt chỗ.'],
];
entries.push(
 ['Akuna','Thực đơn Âu đương đại có hương vị Việt, dùng bữa quanh bếp mở.','Hệ đèn phía trên gợi mặt nước. Bếp phối hợp nguyên liệu địa phương và nhập khẩu trong bộ món nếm thử, có lựa chọn ghép rượu.','Bếp mở|Thực đơn nếm thử|Ghép rượu','Báo trước chế độ ăn và hỏi lựa chọn đồ uống của thực đơn hiện tại.'],
 ['ONVIT','Thực đơn Hàn Quốc dùng nguyên liệu Việt, nổi bật với cháo bào ngư.','Nhà hàng có không gian yên tĩnh. Cháo dùng gạo ST25 và xốt từ gan bào ngư, bên cạnh các món theo bộ của đầu bếp.','Ẩm thực Hàn|Cháo bào ngư|Gạo ST25','Xác nhận bộ món và lựa chọn ghép đồ uống trước khi đặt chỗ.'],
 ['Gia','Thực đơn nếm thử theo mùa, lấy cảm hứng từ ẩm thực Việt.','Thiết kế liên hệ với Văn Miếu ở bên kia đường. Bếp phục vụ một thực đơn, chú trọng tổ hợp vị chua và kết cấu nguyên liệu.','Thực đơn theo mùa|Ẩm thực Việt|Gần Văn Miếu','Báo trước dị ứng và dành thời gian cho toàn bộ thực đơn.'],
 ['Ănăn Saigon','Món đường phố Việt được làm mới trong khu chợ ở trung tâm.','Thực đơn có chả giò gan ngỗng, cá nghệ kiểu Hà Nội và bánh mì nhỏ nhân bò Wagyu theo cách chế biến của bếp.','Món Việt hiện đại|Bánh mì Wagyu|Không khí khu chợ','Kiểm tra thực đơn và đặt bàn theo số người để chọn đủ món chia sẻ.'],
 ['Upstairs','Bữa tối nếm thử trong phòng ăn nhỏ phía trên quán rượu.','Thực đơn Việt đương đại lấy cảm hứng miền Trung; món gỏi bò cà được kết hợp cùng Wagyu và cà tím. Nguồn ghi phòng ăn chỉ có bốn bàn.','Phòng ăn nhỏ|Thực đơn miền Trung|Ghép rượu','Đặt sớm và xác nhận tầng nhà hàng vì lối vào qua khu quán rượu.'],
 ['Tầm Vị','Mâm cơm miền Bắc trong không gian gỗ và đồ trang trí xưa.','Nguồn giới thiệu chả ốc dùng cùng rau, bún và nước mắm, cùng canh cua rau mồng tơi. Quán có sân và thực đơn hình ảnh.','Cơm nhà miền Bắc|Chả ốc|Canh cua','Chọn món mặn, canh và rau theo số người thay vì gọi nhiều phần lớn.'],
 ['Bánh Bèo - Bánh đập','Hai món bánh miền Trung, làm và phục vụ theo từng phần nhỏ.','Bánh bèo có phần xốt thịt, mộc nhĩ, hành và lạc. Bánh đập kết hợp bánh tráng giòn với lớp bánh mềm, dùng cùng nước chấm lên men.','Bánh bèo|Bánh đập|Quán bánh địa phương','Nguồn ghi quán bắt đầu từ giữa chiều; đối chiếu giờ trong ngày trước khi ghé.'],
 ['Miến Lươn Đông Thịnh','Các món miến, cháo và súp cùng nguyên liệu chính là lươn.','Bạn có thể chọn miến nước hoặc miến trộn với lươn chiên, rau, lạc và hành. Súp và cháo có thêm giò cùng nấm hương.','Miến lươn|Cháo lươn|Miến trộn','Nói rõ bạn muốn món nước hay khô khi gọi món.'],
 ['Bún Bò Huế Bà Thương','Bún bò kiểu Huế với nước dùng sả tại Đà Nẵng.','Các lựa chọn trong bát gồm thịt bò thái, giò heo hoặc viên thịt, ăn cùng bún và rau. Vị cay có thể điều chỉnh khi thêm gia vị.','Bún bò Huế|Nước dùng sả|Giò heo','Địa chỉ này ở Đà Nẵng; chọn phần thịt và lượng ớt theo khẩu vị.'],
 ['Bò Kho Gánh','Bò kho phục vụ trong tô đá, ăn cùng bánh mì, mì hoặc cơm.','Nước bò kho có vị đậm từ thịt; quán để sẵn gia vị và các loại xốt để khách tự điều chỉnh.','Bò kho tô đá|Bánh mì|Lựa chọn mì hoặc cơm','Tô đá giữ nhiệt; thử nước dùng trước khi thêm gia vị.'],
 ['Bánh Xèo Tôm Nhảy Cô Ba','Bánh xèo vỏ mỏng kiểu Bình Định với nhân tôm.','Quán gia đình có thêm món ăn nhẹ. Bánh dùng cùng nước mắm hoặc nước chấm lạc; nguồn cũng nhắc tới món nem.','Bánh xèo tôm|Nước chấm lạc|Quán gia đình','Hỏi số bánh trong một phần để chọn đủ cho nhóm.'],
 ['Ăn Thôi','Món Việt trong ngôi nhà hai tầng gần chợ Hàn và sông Hàn.','Mặt tiền xanh vàng và không gian gợi kiến trúc Pháp. Thực đơn gọn, trong đó bánh xèo có nhân thịt, tôm, mực và rau củ.','Bánh xèo|Gần chợ Hàn|Nhà hai tầng','Có thể ghép bữa ăn với hành trình đi bộ quanh chợ; kiểm tra giờ trước khi ghé.'],
 ['Thìa Gỗ','Phở Nam và bánh xèo miền Tây trong không gian nhiều cây.','Quán có khu ngồi ngoài trời và thực đơn qua mã QR. Phở thập cẩm giúp thử nhiều phần thịt bò trong cùng một bát.','Phở Nam|Bánh xèo miền Tây|Khu cây xanh','Xem lựa chọn phần thịt trên thực đơn trước khi chọn bát thập cẩm.'],
 ['Nhà Tú','Món cơm nhà trong không gian có cây xanh và ban công tầng trên.','Nguồn giới thiệu ốc nhồi thịt hấp sả cùng rau củ ăn với kho quẹt và tóp mỡ. Cách phục vụ phù hợp một bữa nhiều món chia sẻ.','Ốc nhồi thịt|Rau kho quẹt|Ban công','Hỏi bàn trong nhà hoặc ban công khi đặt chỗ.'],
 ['Bún Riêu Yến','Bún riêu với nước dùng cà chua, cua và nhiều lựa chọn sợi.','Bát bún có thể thêm thịt ốc và thịt xay. Quán có chỗ ngồi trong nhà lẫn ngoài trời ở góc phố đông người.','Bún riêu|Ốc|Chọn loại sợi','Thử nước trước, rồi thêm từng ít mắm tôm theo khẩu vị.'],
 ['Bánh Xèo 76','Bánh xèo, ram bắp và bún thịt nướng trong quán địa phương.','Bếp than ở lối vào dùng nướng thịt. Ram bắp có nhân ngô, cuốn lớp vỏ mỏng rồi chiên.','Bánh xèo|Ram bắp|Bún thịt nướng','Hỏi các phần bánh và ram để ghép một bữa vừa sức ăn.'],
 ['Bún Chả Cá 109','Bún nước với chả cá chiên hoặc hấp tự làm.','Nước dùng có vị chua nhẹ từ cà chua và dứa. Ngoài chả cá còn có lựa chọn cá ngừ, cá thu và các món từ cua.','Chả cá chiên|Chả cá hấp|Nước dùng cà chua dứa','Nói rõ loại cá và chả muốn thêm trước khi quán chuẩn bị bát.'],
 ['Quán Nhân','Cháo vịt nấu cùng đậu xanh và hạt ý dĩ.','Gạo được ninh trong nước vịt cho kết cấu mềm sánh. Quán còn phục vụ vịt luộc và gỏi vịt để ăn cùng.','Cháo vịt|Vịt luộc|Gỏi vịt','Nếu đi nhóm, hỏi phần vịt ăn kèm cháo để gọi vừa đủ.'],
 ['Bún Chả Cá Hờn','Bún chả cá trong quán gia đình, có lựa chọn bát đặc biệt.','Bát đặc biệt có thịt cua cùng chả cá chiên và luộc. Bạn cũng có thể chọn lát cá thu hoặc cá ngừ; nước dùng cà chua có thêm măng.','Chả cá|Thịt cua|Cá thu hoặc cá ngừ','Hỏi thành phần bát đặc biệt và chọn phần cá theo sở thích.'],
 ['Phở Miến Gà Kỳ Đồng','Phở và miến gà với nước dùng ninh từ xương gà, xương heo.','Thịt gà được thái dùng cùng sợi và nước nóng. Đây là địa chỉ tập trung vào các món gà thay vì một thực đơn nhiều nhóm món.','Phở gà|Miến gà|Nước dùng xương','Chọn loại sợi và phần thịt gà khi gọi món.'],
 ['The East','Bún chả và các món miền Bắc trong ngôi nhà hai tầng.','Chả giò cua, bún chả Hà Nội và bánh flan là các gợi ý từ nguồn. Quán còn trưng bày và bán đồ gốm của nghệ nhân địa phương.','Bún chả|Chả giò cua|Đồ gốm địa phương','Có thể chọn bún chả làm món chính rồi gọi thêm phần nem để chia sẻ.'],
 ['Bún Chả Chan','Bún chả với nhiều lựa chọn thịt nướng và nem chiên.','Ngoài chả viên, bạn có thể chọn ba chỉ hoặc bò cuốn lá lốt. Nước chấm có vị chua ngọt, còn nem được chiên khi gọi.','Bún chả|Ba chỉ nướng|Bò lá lốt','Nguồn ghi chỉ phục vụ đến trưa; kiểm tra giờ và đến sớm.'],
 ['Mặn Mòi (An Khánh)','Món Việt ba miền trong khuôn viên có sân nhiều cây.','Thực đơn có gỏi, canh, món nướng, món kho và lẩu. Không gian sân tạo lựa chọn dùng bữa ngoài trời, cùng quầy quà lưu niệm.','Ẩm thực ba miền|Món kho và lẩu|Sân cây xanh','Chọn đúng chi nhánh An Khánh và hỏi bàn sân khi đặt chỗ.'],
 ['Phở Khôi Hói','Phở bò với nhiều phần thịt để lựa chọn.','Bên cạnh các phần thịt quen thuộc, nguồn nhắc tới phần bắp gót. Bạn có thể nói rõ độ chín của thịt khi quán chuẩn bị bát.','Phở bò|Chọn phần thịt|Tùy độ chín','Hỏi các phần thịt đang có thay vì chỉ gọi một bát chung chung.'],
 ['Ngọc Chi','Món chay dùng rau địa phương, có hoành thánh và chả giò.','Thực đơn phần lớn là món Việt, một số món dùng đạm thực vật và gia vị lên men. Canh chua rau củ là một lựa chọn khởi đầu.','Ẩm thực chay|Hoành thánh|Chả giò','Hỏi món có dùng trứng, sữa hoặc gia vị cần tránh nếu ăn thuần chay.'],
 ['Bà Đông','Bún mắm nêm với heo quay và các lựa chọn đồ ăn kèm.','Nước mắm nêm được pha cùng ớt, tỏi và trái cây. Phần thập cẩm có thêm chả và nem, bên cạnh lựa chọn nước mía.','Bún mắm nêm|Heo quay|Nước mía','Nói rõ lượng mắm và phần thịt bạn muốn trong bát.'],
 ['Bánh Xèo 46A','Bánh xèo cỡ lớn nhân đậu xanh, giá, thịt heo và tôm.','Quán có chỗ ngồi gần bếp mở và phòng điều hòa. Ngoài bánh xèo còn có gỏi gà cùng các món thịt, hải sản nướng.','Bánh xèo lớn|Gỏi gà|Món nướng','Gọi bánh theo sức ăn vì một bánh có thể chia nhiều người.'],
 ['Bun Cha Ta (Nguyen Huu Huan Street)','Bún chả và nem chiên, có lựa chọn món chay.','Thịt nướng và chả viên dùng cùng bún, nước chấm. Nem có các lựa chọn cua hải sản hoặc gà; món chay gồm bún với đậu phụ và sốt cà chua.','Bún chả|Nem cua|Lựa chọn món chay','Kiểm tra đúng địa chỉ Nguyễn Hữu Huân và báo rõ yêu cầu món chay.'],
 ['Phở Phượng','Phở bò với nhiều phần thịt, trong đó có đuôi bò ninh mềm.','Rau ăn kèm được chuẩn bị riêng. Phần đặc biệt giúp thử nhiều loại thịt trong cùng bát nước phở.','Phở bò|Đuôi bò|Phần đặc biệt','Hỏi đuôi bò còn phục vụ không và giá phần thêm trên thực đơn.'],
 ['Phở Hương Bình','Phở gà hoặc phở bò với nước dùng trong.','Bạn có thể thêm da gà, lòng đỏ trứng, nạm hoặc gân tùy món. Nước dùng được chuẩn bị hằng ngày theo hồ sơ nguồn.','Phở gà|Phở bò|Các phần thêm','Chọn phần thịt và topping trước khi quán chuẩn bị bát.'],
 ['Phở Lệ (An Đông)','Phở bò kiểu miền Nam với nước dùng đậm và phần ăn lớn.','Bát thập cẩm có bò tái, bò chín, nạm, bò viên và gân. Quán có không khí đông khách của một hàng phở lâu năm.','Phở miền Nam|Bò viên|Phở thập cẩm','Chọn đúng chi nhánh An Đông và hỏi cỡ bát theo sức ăn.'],
 ['Bánh Cuốn Gia Truyền Thanh Vân (Hang Ga Street)','Bánh cuốn làm tại chỗ với các lựa chọn nhân thịt, tôm hoặc gà.','Lớp bánh mỏng dùng cùng nước chấm gia đình pha vị mặn, ngọt và chua. Quán có thêm bún thang trong thực đơn.','Bánh cuốn nóng|Chọn nhân bánh|Bún thang','Xác nhận đúng cơ sở Hàng Gà và hỏi loại nhân đang phục vụ.'],
 ['Chào Bạn (98 To Ngoc Van Street)','Món Việt được biến tấu, có nem cua và các món đặc biệt của bếp.','Nguồn giới thiệu tôm với kem dừa và sườn heo phủ xốt. Không khí quán hướng tới một bữa ăn thoải mái cùng bạn bè.','Nem cua|Tôm kem dừa|Sườn heo','Chọn đúng địa chỉ 98 Tô Ngọc Vân và hỏi phần món đặc biệt trong ngày.'],
 ['Phở Gia Truyền (Hoàn Kiếm)','Phở bò kiểu Bắc tại phố Bát Đàn.','Các phần thịt gồm tái, tái lăn hoặc nạm chín theo cách gọi của quán. Bát được chuẩn bị ở quầy, có thể thêm quẩy hay lòng đỏ trứng.','Phở bò Bắc|Bát Đàn|Quẩy ăn kèm','Đối chiếu cách gọi phần thịt tại quầy trước khi thanh toán.'],
 ['Lê Gia Khang (Ngũ Hành Sơn)','Bún bò kiểu Huế với lựa chọn xí quách.','Ngoài phần xương lớn còn có bát thập cẩm với huyết, chả và gân; lưỡi bò là một lựa chọn được nguồn nhắc tới.','Bún bò|Xí quách|Bát thập cẩm','Đến sớm nếu muốn gọi xí quách vì số phần có hạn.'],
 ['Bánh Cuốn Tây Hồ 127','Bánh cuốn được làm khi gọi, trong quán hai tầng.','Thực đơn có nhân thịt heo với củ sắn và lựa chọn món chay. Nguồn còn giới thiệu một loại bánh đậu chiên dùng như món ăn nhẹ.','Bánh cuốn nóng|Lựa chọn chay|Bánh đậu chiên','Hỏi thành phần nhân và nước chấm nếu chọn món chay.'],
 ['Quê Xưa (Hòa Cường)','Mì Quảng và bánh tráng cuốn thịt heo trong quán hai tầng.','Bánh tráng cuốn dùng cùng thịt ba chỉ luộc, bánh phở và rau; nước chấm pha từ mắm cá cơm với trái cây.','Mì Quảng|Bánh tráng thịt heo|Mắm nêm','Giờ đông khách có thể ngồi ghép bàn; hỏi trước nếu đi nhóm đông.'],
 ['Bún Bò Bà Rơi (Hoà Cường)','Bún bò theo cách nấu của gia đình gốc Huế tại Đà Nẵng.','Nước dùng được ninh với thịt và xương bò. Các phần thêm có gân, sườn, nạm, lưỡi, giò heo và viên cua.','Bún bò Huế|Nhiều phần thịt|Bát đặc biệt','Hỏi thành phần bát đặc biệt nếu muốn thử nhiều topping.'],
 ['Nam Hìn (Phan Thanh Street)','Bánh xèo và bánh tráng thịt heo trong không gian nhiều cây.','Bánh xèo có thể chọn bò, mực hoặc tôm, ăn cùng rau và xốt lạc. Bánh tráng cuốn dùng thịt ba chỉ với mắm cá cơm lên men.','Bánh xèo|Bánh tráng thịt heo|Xốt lạc','Báo trước nếu cần tránh lạc hoặc mắm lên men.'],
 ['Hồng Phát (Bàn Cờ)','Hủ tiếu cùng các món chiên mang ảnh hưởng Hoa và Khmer.','Các phần hủ tiếu có thịt xay, gan, tôm hoặc huyết. Bạn có thể gọi chả giò tôm cua và sủi cảo chiên để ăn kèm.','Hủ tiếu|Chả giò tôm cua|Sủi cảo chiên','Xác nhận cơ sở Bàn Cờ và chọn món nước hoặc món khô theo thực đơn.'],
);
export const editorial=new Map(entries.map(([name,hook,summary,highlights,tip])=>[name,{hook,summary:hook+' '+summary,highlights:highlights.split('|'),tips:[tip]}]));

