editorial.set('May Home Tà Xùa',{hook:'Chỗ ở có nhận nhóm tại khu Tà Xùa theo cẩm nang.',summary:'Chỗ ở có nhận nhóm tại khu Tà Xùa theo cẩm nang. Nguồn ghi nhận các nhóm nhỏ và đoàn lớn; sức chứa cụ thể, loại phòng và bữa ăn cần xác nhận theo ngày.',highlights:['Lưu trú theo nhóm','Khu Tà Xùa'],tips:['Liên hệ trước để chốt số người, phòng riêng hay tập thể và việc đặt bữa ăn.']});
